// Controller public R invariants over the original retained fixed fixture only.
#![forbid(unsafe_code)]
use serde_json::{Value,json};
use std::{cell::Cell,panic::{catch_unwind,AssertUnwindSafe}};
use water_contracts::v1::{self as a,OpaqueId,ProtectionReason,Risk};
use water_native_scan::v1 as r;
use water_scope_registry::v1::{Registry,RegistryError,RegisteredScope};
fn id(s:&str)->OpaqueId{OpaqueId::new(s).unwrap()}
fn fixture()->Value{serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_NATIVE_WALK_INDEX").unwrap()).unwrap()).unwrap()}
fn setup(i:&Value)->(Registry,RegisteredScope){let mut reg=Registry::new(4).unwrap();let p=reg.prepare(&id("independent-r-scope"),i["root"].as_str().unwrap()).unwrap();let scope=reg.confirm(&p).unwrap();(reg,scope)}
fn check(scan:&r::NativeScan)->Value{a::validate_report(scan.report()).unwrap();let q=water_redacted_report::v1::to_json(&water_redacted_report::v1::redact_report(scan.report()).unwrap()).unwrap();assert_eq!(r::redacted_json(scan).unwrap(),q);assert!(!q.contains("alpha.txt")&&!q.contains("TRAP_OUTSIDE"));let v:Value=serde_json::from_str(&r::to_json(scan).unwrap()).unwrap();assert_eq!(v["recorded_entries"],json!(scan.report().findings.len()));assert!(scan.report().totals.logical_bytes.is_none());for f in &scan.report().findings{assert_eq!(f.risk,Risk::Protected);let prefix=format!("{}/",f.relative_path.as_str());let descendant=scan.report().findings.iter().any(|c|c.scope_id==f.scope_id&&c.relative_path.as_str().starts_with(&prefix));let mut expected=vec![ProtectionReason::UnknownOwnership,ProtectionReason::IncompleteEvidence];if descendant{expected.push(ProtectionReason::ProtectedDescendant);}assert_eq!(f.protection_reasons,expected);}assert!(!v.to_string().contains("TRAP_OUTSIDE"));v}
#[test]fn budget_matrix_uses_actual_recorded_descendants(){let i=fixture();let(mut reg,scope)=setup(&i);for depth in [0,1,3]{for count in 1..=9{for names in [6,7,32]{let scan=r::scan_registered(&mut reg,&scope,i["root"].as_str().unwrap(),&id("budget-matrix"),&r::ScanOptions::new(depth,count,names).unwrap(),&r::CancelToken::new()).unwrap();let v=check(&scan);assert!(v["visited_entries"].as_u64().unwrap()<=count as u64);assert!(v["recorded_entries"].as_u64().unwrap()<=v["visited_entries"].as_u64().unwrap());if depth>0&&names==6{assert_eq!(v["visited_entries"],0);assert_eq!(v["recorded_entries"],0);assert_eq!(v["status"],"partial");}let permit=reg.begin_scan(&scope).unwrap();reg.finish(&permit).unwrap();}}}reg.revoke(&scope).unwrap();}
struct Stop{at:u32,cancel:r::CancelToken,panic:bool,seen:Cell<u32>}
impl r::ScanObserver for Stop{fn on_entry(&self,p:&r::ScanProgress){self.seen.set(self.seen.get()+1);assert_eq!(p.recorded_entries,self.seen.get());if p.recorded_entries==self.at{assert!(!self.panic,"controller expected observer unwind");self.cancel.cancel();}}}
#[test]fn cancellation_prefixes_and_unwind_release_attempt(){let i=fixture();let(mut reg,scope)=setup(&i);let options=r::ScanOptions::new(8,128,32).unwrap();let complete=r::scan_registered(&mut reg,&scope,i["root"].as_str().unwrap(),&id("complete"),&options,&r::CancelToken::new()).unwrap();let expected=check(&complete)["entries"].as_array().unwrap().clone();for at in 1..=8{let cancel=r::CancelToken::new();let observer=Stop{at,cancel:cancel.clone(),panic:false,seen:Cell::new(0)};let scan=r::scan_registered_with_observer(&mut reg,&scope,i["root"].as_str().unwrap(),&id("prefix"),&options,&cancel,&observer).unwrap();let v=check(&scan);assert_eq!(v["entries"].as_array().unwrap(),&expected[..at as usize]);assert_eq!(v["status"],if at==8{"completed"}else{"cancelled"});}let observer=Stop{at:3,cancel:r::CancelToken::new(),panic:true,seen:Cell::new(0)};assert!(catch_unwind(AssertUnwindSafe(||r::scan_registered_with_observer(&mut reg,&scope,i["root"].as_str().unwrap(),&id("panic"),&options,&observer.cancel,&observer))).is_err());let permit=reg.begin_scan(&scope).unwrap();reg.finish(&permit).unwrap();reg.revoke(&scope).unwrap();}
#[test]fn rejected_calls_preserve_host_attempt_and_precancel_avoids_candidate(){let i=fixture();let(mut reg,scope)=setup(&i);let options=r::ScanOptions::new(8,128,32).unwrap();let permit=reg.begin_scan(&scope).unwrap();assert!(matches!(r::scan_registered(&mut reg,&scope,i["trap"].as_str().unwrap(),&id("occupied"),&options,&r::CancelToken::new()),Err(r::NativeScanError::Source(RegistryError::WrongState))));reg.check_permit(&permit).unwrap();reg.finish(&permit).unwrap();assert!(matches!(r::scan_registered(&mut reg,&scope,i["trap"].as_str().unwrap(),&id("mismatch"),&options,&r::CancelToken::new()),Err(r::NativeScanError::RootMismatch)));let token=r::CancelToken::new();std::thread::spawn({let t=token.clone();move||t.cancel()}).join().unwrap();let cancelled=r::scan_registered(&mut reg,&scope,i["missing"].as_str().unwrap(),&id("precancel"),&options,&token).unwrap();let v=check(&cancelled);assert_eq!(v["status"],"cancelled");assert_eq!(v["visited_entries"],0);assert_eq!(v["issues"][0]["relative_path"],Value::Null);let permit=reg.begin_scan(&scope).unwrap();reg.finish(&permit).unwrap();reg.revoke(&scope).unwrap();assert!(r::scan_registered(&mut reg,&scope,i["root"].as_str().unwrap(),&id("revoked"),&options,&r::CancelToken::new()).is_err());}
